import { useLocation, useNavigate } from 'react-router-dom';

const Login = ({ setIsLoggedIn }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from || "/"; // 가려던 페이지 정보가 있으면 저장

  const handleLogin = () => {
    setIsLoggedIn(true);
    navigate(from); // 로그인 후 원래 가려던 곳으로 보냄
  };

  return (
    <div>
      <h2>로그인</h2>
      <button onClick={handleLogin}>로그인 완료</button>
      <button onClick={() => navigate('/signup')}>회원가입 하러가기</button>
    </div>
  );
};
